      try { if (window.TipOutDateState) TipOutDateState.assertDateWritable(scope.store, scope.dateKey); }
      catch (error) { showNotification(error.message, 'error'); renderDetailPage(); return; }
      var table = input.closest('table');
      input.closest('tr').setAttribute('data-hours-manual', '1');
      try { if (table) onEmpHoursChange(table.id); }
