      container.innerHTML = '';
      existingManualConditions = {};
      var cond = poolRuleConditions[ruleId];
      if (cond && typeof cond === 'object') {
        normalizeConditionsRoleEmployeeExclusive(cond);
        sortPoolConditionLoadKeys(Object.keys(cond)).forEach(function(type) {
          if (type === 'weekdays') {
            addManualCondition('weekday', true);
            setManualConditionValue('weekday', cond.weekdays);
            return;
          }
          if (type !== 'role' && type !== 'employee' && type !== 'hours' && type !== 'shift') return;
          addManualCondition(type, true);
          if (type === 'role') setManualConditionValue(type, { role: cond.role || [] });
          else if (type === 'employee') setManualConditionValue(type, { employeeRoles: cond.employeeRoles, employees: cond.employee });
          else setManualConditionValue(type, cond[type]);
        });
      }
      updateManualConditionMenu();
