      if (Array.isArray(value)) {
        emps = value.slice();
      } else if (typeof value === 'object') {
        emps = Array.isArray(value.employees) ? value.employees.slice() : (Array.isArray(value.employee) ? value.employee.slice() : []);
        roles = Array.isArray(value.roles) ? value.roles.slice() : (Array.isArray(value.employeeRoles) ? value.employeeRoles.slice() : []);
      }
      if (!roles.length && emps.length) roles = inferEmployeeFilterRolesFromNames(emps);
      return { roles: roles, employees: emps };
